func ProviderInfo() tfbridge.ProviderInfo {
	return tfbridge.ProviderInfo{
		P:    sdkv2.NewProvider(Provider()),
		Name: "tpsdkv2",

		PreConfigureCallback: func(vars resource.PropertyMap, config shim.ResourceConfig) error {
			return nil
		},
	}
}

