							}),
						}),
					}),
				}),
			}),
		},
		{
			name:   "Regress an issue with set values being parsed as tuples",
			schema: testprovider.ProviderV2().ResourcesMap["example_resource"],
			config: (func() map[string]interface{} {
				data := map[string]interface{}{
					"string_property_value": "foo",
					"set_property_value":    []interface{}{"e1", "e2"},
				}
				return data
			})(),
			expected: cty.ObjectVal(map[string]cty.Value{
				"string_property_value": cty.StringVal("foo"),
				"set_property_value": cty.SetVal([]cty.Value{
					cty.StringVal("e1"),
					cty.StringVal("e2"),
				}),
			}),
		},
		{
			name: "Regress aws 3094",
			schema: func() *schema.Resource {
				securityGroupRuleNestedBlock := &schema.Resource{
					Schema: map[string]*schema.Schema{
						"from_port": {
							Type:     schema.TypeInt,
							Required: true,
						},
						"to_port": {
							Type:     schema.TypeInt,
							Required: true,
						},
						"cidr_blocks": {
							Type:     schema.TypeList,
							Optional: true,
							Elem: &schema.Schema{
								Type: schema.TypeString,
							},
						},
					},
				}
				ingress := &schema.Schema{
					Type:       schema.TypeSet,
					Optional:   true,
					Computed:   true,
					ConfigMode: schema.SchemaConfigModeAttr,
					Elem:       securityGroupRuleNestedBlock,
					Set: func(i interface{}) int {
						return 0
					},
				}
				return &schema.Resource{
					Schema: map[string]*schema.Schema{
						"arn": {
							Type:     schema.TypeString,
							Computed: true,
						},
						"ingress": ingress,
					},
				}
			}(),
			config: map[string]interface{}{
				"ingress": []interface{}{
					map[string]interface{}{
						"to_port":   terraformUnknownVariableValue,
						"from_port": terraformUnknownVariableValue,
					},
				},
			},
			expected: cty.ObjectVal(map[string]cty.Value{
				"ingress": cty.SetVal([]cty.Value{
					cty.ObjectVal(map[string]cty.Value{
						"cidr_blocks": cty.NullVal(cty.List(cty.String)),
						"from_port":   cty.UnknownVal(cty.Number),
						"to_port":     cty.UnknownVal(cty.Number),
					}),
				}),
			}),
		},
	}

	for _, c := range cases {
		t.Run(c.name, func(t *testing.T) {
			if c.skip {
				t.Skip()
			}

			resourceConfig := &terraform.ResourceConfig{Raw: c.config}
			config := makeResourceRawConfig(PlanState, resourceConfig, c.schema)

			actualMap := config.AsValueMap()
			expectedMap := c.expected.AsValueMap()

			keys := map[string]bool{}

			for k := range actualMap {
				keys[k] = true
			}

			for k := range expectedMap {
				keys[k] = true
			}

			for k := range keys {
				ev, gotEv := expectedMap[k]
				av, gotAv := actualMap[k]
				switch {
				case gotAv && !gotEv && !av.IsNull(): // tolerate Null to avoid spelling it out in expected
					t.Errorf("Key %q has an unexpected entry %v", k, av.GoString())
				case !gotAv && gotEv:
					t.Errorf("Key %q is missing an entry, expecting %v", k, av.GoString())
				case gotAv && gotEv && !av.RawEquals(ev):
					t.Errorf("Key %q expected to have a value %v but got %v", k, ev.GoString(), av.GoString())
				}
			}
		})
	}
}

func TestRecoverCtyValue(t *testing.T) {
	type testCase struct {
		name   string
		dT     cty.Type
		value  any
		expect cty.Value
	}

	cases := []testCase{
		{"null", cty.EmptyObject, nil, cty.NullVal(cty.EmptyObject)},
		{
			"object with mismatched fields",
			cty.Object(map[string]cty.Type{
				"x": cty.String,
				"y": cty.Bool,
			}),
			map[string]any{
				"y": true,
				"z": "ignored",
			},
			cty.ObjectVal(map[string]cty.Value{
				"x": cty.NullVal(cty.String),
				"y": cty.BoolVal(true),
			}),
		},
		{
			"tuple",
			cty.Tuple([]cty.Type{cty.String, cty.Number}),
			[]interface{}{"A", 42},
			cty.TupleVal([]cty.Value{cty.StringVal("A"), cty.NumberIntVal(42)}),
		},
		{
			"empty object",
			cty.EmptyObject,
			map[string]interface{}{},
			cty.EmptyObjectVal,
		},
		{
			"empty tuple",
			cty.EmptyTuple,
			[]interface{}{},
			cty.EmptyTupleVal,
		},
		{
			"empty map",
			cty.Map(cty.String),
			map[string]interface{}{},
			cty.MapValEmpty(cty.String),
		},
		{
			"empty list",
			cty.List(cty.String),
			[]any{},
			cty.ListValEmpty(cty.String),
		},
		{
			"empty set",
			cty.Set(cty.String),
			[]interface{}{},
			cty.SetValEmpty(cty.String),
		},
		{"int", cty.Number, int(42), cty.NumberIntVal(42)},
		{"int64", cty.Number, int64(42), cty.NumberIntVal(42)},
		{"uint8", cty.Number, uint8(42), cty.NumberIntVal(42)},
		{"uint16", cty.Number, uint16(42), cty.NumberIntVal(42)},
		{"uint32", cty.Number, uint32(42), cty.NumberIntVal(42)},
		{"uint64", cty.Number, uint64(42), cty.NumberIntVal(42)},
		{"int8", cty.Number, int8(42), cty.NumberIntVal(42)},
		{"int16", cty.Number, int16(42), cty.NumberIntVal(42)},
		{"int32", cty.Number, int32(42), cty.NumberIntVal(42)},
		{"int64", cty.Number, int64(42), cty.NumberIntVal(42)},
		{"float64", cty.Number, float64(1.42), cty.NumberFloatVal(1.42)},
		{"float32", cty.Number, float32(1.42), cty.NumberFloatVal(float64(float32(1.42)))},
		{"big.Float", cty.Number, big.NewFloat(1.42), cty.NumberVal(big.NewFloat(1.42))},
	}

	for _, tc := range cases {
		tc := tc
		t.Run(tc.name, func(t *testing.T) {
			r, err := recoverCtyValue(tc.dT, tc.value)
			require.NoError(t, err)
			require.Truef(t, tc.expect.RawEquals(r), "expected %s to equal %s",
				r.GoString(), tc.expect.GoString())
		})
	}
}

func TestRecoverAndCoerceCtyValue(t *testing.T) {
	rapid.Check(t, func(t *rapid.T) {
		depth := 3
		res := rapidgen.ResourceProperGen(depth).Draw(t, "res")
		t.Logf("res.CoreConfigSchema().ImpliedType() == %v", res.CoreConfigSchema().ImpliedType().GoString())
		m := valueMapGen(valueGen(depth-1)).Draw(t, "m")
		v, err := schema.JSONMapToStateValue(m, res.CoreConfigSchema())
		if err != nil {
			return
		}
		result, err := recoverAndCoerceCtyValue(res, m)
		if err != nil {
			t.Fatalf("got an error from recoverAndCoerceCtyValue: %v", err)
		}

		v = normalizeCtyValue(v)
		result = normalizeCtyValue(result)
		require.Equal(t, result, v)
	})
}

func normalizeCtyValue(v cty.Value) cty.Value {
	v, err := cty.Transform(v, func(p cty.Path, v cty.Value) (cty.Value, error) {
		if v.IsWhollyKnown() && !v.IsNull() && v.Type() == cty.Number {
			f := v.AsBigFloat()
			f.SetPrec(512)
			return cty.NumberVal(f), nil
		}
		return v, nil
	})
	contract.AssertNoErrorf(err, "Transform should never fail here")
	return v
}

func numGen() *rapid.Generator[interface{}] {
	return rapid.OneOf(
		rapid.IntRange(0, 2).AsAny(),
		rapid.Int8Range(0, 2).AsAny(),
		rapid.Int16Range(0, 2).AsAny(),
		rapid.Int32Range(0, 2).AsAny(),
		rapid.Int64Range(0, 2).AsAny(),
		rapid.UintRange(0, 2).AsAny(),
		rapid.Uint8Range(0, 2).AsAny(),
		rapid.Uint16Range(0, 2).AsAny(),
		rapid.Uint32Range(0, 2).AsAny(),
		rapid.Uint64Range(0, 2).AsAny(),
		rapid.SampledFrom([]float32{0, 1}).AsAny(),
		rapid.SampledFrom([]float64{0, 1}).AsAny(),
	)
}

func valueGen(depth int) *rapid.Generator[interface{}] {
	scalars := []interface{}{
		nil,
		true, false,
		"", "s",
	}
	s := rapid.OneOf(rapid.SampledFrom(scalars), numGen())
	if depth == 0 {
		return s
	}

	g := valueGen(depth - 1)
	return rapid.OneOf(
		s,
		rapid.SliceOf(g).AsAny(),
		valueMapGen(g).AsAny(),
	)
}

func valueMapGen(g *rapid.Generator[interface{}]) *rapid.Generator[map[string]interface{}] {
	return rapid.MapOfN(rapidgen.PropertyNameGen(), g, 0, 2)
}

